import {fieldDefaults} from './store.mjs';

const companyFields=['contractor','informationRole','coordinationScope','cde','submissionPlatform','worksharingMode','informationStates','reviewWorkflow','backupLocation','backupFrequency','retention','namingPattern','originatorCode','drawingStrategy','units','loinSystem','classification','modelSizeLimit','authoringProcedure','coordinationCycle','issuePlatform','issueWorkflow','qaFrequency','warningPolicy','asBuiltMethod'];
const companyLists=['responsibilities','software','namingFields','meetings','qaChecks'];
const clientFields=['client','consultant','cde','cdeUrl','submissionPlatform','informationStates','suitabilitySystem','reviewWorkflow','namingPattern','drawingStrategy','crs','verticalDatum','units','ursReference','loinSystem','classification','modelSizeLimit','assetSchema','cobieVersion','asBuiltAccuracy'];
const clientLists=['references','uses','exchanges','namingFields','loin','milestones','deliverables','clashes','assetRequirements','appendices'];

export function captureTemplate(project,type,meta={}){const company=type==='company',fields=company?companyFields:clientFields,lists=company?companyLists:clientLists;return {id:meta.id||crypto.randomUUID(),type,name:meta.name||'Untitled template',description:meta.description||'',sourceReference:meta.sourceReference||'',version:meta.version||'1.0',isDefault:Boolean(meta.isDefault),data:{fields:Object.fromEntries(fields.map(k=>[k,project.fields[k]||''])),lists:Object.fromEntries(lists.map(k=>[k,structuredClone(project.lists[k]||[])])),moduleStates:company?{}:structuredClone(project.moduleStates)},createdAt:meta.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};}
export function previewTemplate(project,template){const conflicts=[];for(const [key,value] of Object.entries(template.data.fields||{}))if(value&&project.fields[key]&&project.fields[key]!==fieldDefaults[key]&&project.fields[key]!==value)conflicts.push({area:'Field',key,current:project.fields[key],incoming:value});for(const [key,rows] of Object.entries(template.data.lists||{}))if(rows.length&&project.lists[key]?.length)conflicts.push({area:'Schedule',key,current:`${project.lists[key].length} rows`,incoming:`${rows.length} rows`});for(const [key,value] of Object.entries(template.data.moduleStates||{}))if(project.moduleStates[key]!==value)conflicts.push({area:'Module',key,current:project.moduleStates[key],incoming:value});return {conflicts,fields:Object.keys(template.data.fields||{}).length,schedules:Object.keys(template.data.lists||{}).length,rows:Object.values(template.data.lists||{}).reduce((n,r)=>n+r.length,0),modules:Object.keys(template.data.moduleStates||{}).length};}
export function applyTemplate(project,template,mode='fill'){const impact=previewTemplate(project,template);for(const [key,value] of Object.entries(template.data.fields||{})){if(mode==='overwrite'||!project.fields[key]||project.fields[key]===fieldDefaults[key])project.fields[key]=value;}for(const [key,rows] of Object.entries(template.data.lists||{})){if(mode==='overwrite')project.lists[key]=structuredClone(rows);else{const existing=project.lists[key]||[],seen=new Set(existing.map(x=>JSON.stringify(x)));project.lists[key]=[...existing,...structuredClone(rows).filter(x=>!seen.has(JSON.stringify(x)))];}}if(template.type==='client'){if(mode==='overwrite')Object.assign(project.moduleStates,template.data.moduleStates||{});else for(const [key,value] of Object.entries(template.data.moduleStates||{}))if(project.moduleStates[key]==='not_applicable'&&value!=='not_applicable')project.moduleStates[key]=value;}project.appliedTemplates.push({id:template.id,name:template.name,type:template.type,version:template.version,sourceReference:template.sourceReference||'',mode,appliedAt:new Date().toISOString()});project.templateConflicts=mode==='overwrite'?[]:impact.conflicts.map(c=>({...c,templateId:template.id,templateName:template.name}));return impact;}
